package com.runeversus;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Assert;
import org.junit.Test;

public class WiseOldManGainsClientTest
{
	private static final MediaType JSON = MediaType.parse("application/json");

	@Test
	public void identifiesRequestsAndCachesRepeatedPlayerGains() throws Exception
	{
		AtomicInteger requests = new AtomicInteger();
		AtomicReference<Request> captured = new AtomicReference<>();
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			requests.incrementAndGet();
			captured.set(chain.request());
			return response(chain.request(), 200,
				"{\"data\":{\"skills\":{\"overall\":{\"experience\":{\"gained\":123}}}}}");
		}).build();
		WiseOldManRequestGate gate = new WiseOldManRequestGate(
			20, 60_000L, System::currentTimeMillis);
		WiseOldManGainsClient client = new WiseOldManGainsClient(http, new Gson(), gate);

		Assert.assertEquals(123L,
			client.getSkillExperienceGains("Alice", "day").get(net.runelite.client.hiscore.HiscoreSkill.OVERALL).longValue());
		client.getSkillExperienceGains("Alice", "day");

		Assert.assertEquals(1, requests.get());
		Assert.assertTrue(captured.get().header("User-Agent").startsWith("RuneVersus/"));
		Assert.assertEquals("application/json", captured.get().header("Accept"));
	}

	@Test
	public void turnsHttp429IntoSharedRetryAfterCooldown() throws Exception
	{
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain ->
			response(chain.request(), 429, "{}", "Retry-After", "12")).build();
		WiseOldManRequestGate gate = new WiseOldManRequestGate(
			20, 60_000L, System::currentTimeMillis);
		WiseOldManGainsClient client = new WiseOldManGainsClient(http, new Gson(), gate);

		try
		{
			client.getSkillExperienceGains("Alice", "day");
			Assert.fail("Expected WOM HTTP 429 to trigger backoff");
		}
		catch (WiseOldManRateLimitException ex)
		{
			Assert.assertEquals(12L, ex.getRetryAfterSeconds());
		}
	}

	@Test
	public void safelyEncodesPlayerNamesAsOnePathSegment() throws Exception
	{
		AtomicReference<Request> captured = new AtomicReference<>();
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			captured.set(chain.request());
			return response(chain.request(), 200, "{\"data\":{\"skills\":{}}}");
		}).build();
		WiseOldManGainsClient client = new WiseOldManGainsClient(http, new Gson(), new WiseOldManRequestGate(
			20, 60_000L, System::currentTimeMillis));

		client.getSkillExperienceGains("Alice Bob", "day");

		Assert.assertEquals("/v2/players/Alice%20Bob/gained", captured.get().url().encodedPath());
	}

	@Test
	public void rejectsInvalidPlayerNamesBeforeCallingWiseOldMan() throws Exception
	{
		AtomicInteger requests = new AtomicInteger();
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			requests.incrementAndGet();
			return response(chain.request(), 200, "{}");
		}).build();
		WiseOldManGainsClient client = new WiseOldManGainsClient(http, new Gson(), new WiseOldManRequestGate(
			20, 60_000L, System::currentTimeMillis));

		try
		{
			client.getSkillExperienceGains("Alice/Bob", "day");
			Assert.fail("Expected an invalid RSN to be rejected");
		}
		catch (java.io.IOException expected)
		{
			Assert.assertTrue(expected.getMessage().contains("RSN"));
		}
		Assert.assertEquals(0, requests.get());
	}

	@Test
	public void toleratesUnexpectedMetricValueTypes() throws Exception
	{
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain ->
			response(chain.request(), 200,
				"{\"data\":{\"skills\":{\"overall\":{\"experience\":[]}}}}"))
			.build();
		WiseOldManGainsClient client = new WiseOldManGainsClient(http, new Gson(), new WiseOldManRequestGate(
			20, 60_000L, System::currentTimeMillis));

		Assert.assertTrue(client.getSkillExperienceGains("Alice", "day").isEmpty());
	}

	@Test
	public void rejectsUnexpectedlyLargeGroupArrays() throws Exception
	{
		StringBuilder json = new StringBuilder("[");
		for (int index = 0; index < 2_001; index++)
		{
			if (index > 0)
			{
				json.append(',');
			}
			json.append("{}");
		}
		json.append(']');
		OkHttpClient http = new OkHttpClient.Builder().addInterceptor(chain ->
			response(chain.request(), 200, json.toString())).build();
		WiseOldManGainsClient client = new WiseOldManGainsClient(http, new Gson(), new WiseOldManRequestGate(
			20, 60_000L, System::currentTimeMillis));

		try
		{
			client.getGroupGains(139, GainPeriod.DAY);
			Assert.fail("Expected an oversized group array to be rejected");
		}
		catch (java.io.IOException expected)
		{
			Assert.assertTrue(expected.getMessage().contains("too many"));
		}
	}

	@Test
	public void parsesMonthlyLeagueEfficiencyAndCollectionGains()
	{
		String json = "[{"
			+ "\"player\":{\"id\":4156,\"username\":\"alice\",\"displayName\":\"Alice\",\"type\":\"ironman\"},"
			+ "\"startDate\":\"2026-07-01T01:00:00Z\","
			+ "\"endDate\":\"2026-07-20T12:00:00Z\","
			+ "\"data\":["
			+ "{\"metric\":\"ehp\",\"gained\":12.75},"
			+ "{\"metric\":\"ehb\",\"gained\":8.5},"
			+ "{\"metric\":\"collections_logged\",\"gained\":6},"
			+ "{\"metric\":\"overall\",\"gained\":1234567}]}]";

		List<MonthlyLeagueParticipant> parsed = WiseOldManGainsClient.parseMonthlyLeagueGains(
			new Gson().fromJson(json, JsonArray.class));

		Assert.assertEquals(1, parsed.size());
		MonthlyLeagueParticipant participant = parsed.get(0);
		Assert.assertEquals(4156L, participant.getPlayerId());
		Assert.assertEquals("Alice", participant.getName());
		Assert.assertEquals("ironman", participant.getAccountType());
		Assert.assertEquals(12.75, participant.getEhpGained(), 0.001);
		Assert.assertEquals(8.5, participant.getEhbGained(), 0.001);
		Assert.assertEquals(6L, participant.getCollectionsGained());
		Assert.assertEquals(Instant.parse("2026-07-01T01:00:00Z"), participant.getTrackedFrom());
	}

	@Test
	public void parsesClanJoinDateFromGroupMemberships()
	{
		String json = "{\"memberships\":[{"
			+ "\"playerId\":4156,"
			+ "\"clientSyncJoinedAt\":\"2026-06-14T12:00:00Z\","
			+ "\"createdAt\":\"2026-06-20T12:00:00Z\","
			+ "\"player\":{\"id\":4156,\"displayName\":\"Alice\",\"type\":\"ironman\"}}]}";

		List<MonthlyLeagueMembership> memberships = WiseOldManGainsClient.parseGroupMemberships(
			new Gson().fromJson(json, JsonObject.class));

		Assert.assertEquals(1, memberships.size());
		Assert.assertEquals(4156L, memberships.get(0).getPlayerId());
		Assert.assertEquals("Alice", memberships.get(0).getName());
		Assert.assertEquals(Instant.parse("2026-06-14T12:00:00Z"), memberships.get(0).getJoinedAt());
	}

	@Test
	public void parsesOverallCollectionsAndSummedBossKc()
	{
		String json = "[{"
			+ "\"player\":{\"username\":\"alice\",\"displayName\":\"Alice\"},"
			+ "\"data\":["
			+ "{\"metric\":\"overall\",\"gained\":123456},"
			+ "{\"metric\":\"collections_logged\",\"gained\":2},"
			+ "{\"metric\":\"vorkath\",\"gained\":10},"
			+ "{\"metric\":\"chambers_of_xeric\",\"gained\":5},"
			+ "{\"metric\":\"attack\",\"gained\":99999}]}]";

		JsonArray root = new Gson().fromJson(json, JsonArray.class);
		Map<String, ClanProgressGains> parsed = WiseOldManGainsClient.parseGroupGains(root);

		Assert.assertEquals(1, parsed.size());
		ClanProgressGains gains = parsed.get("Alice");
		Assert.assertNotNull(gains);
		Assert.assertEquals(123456L, gains.getXp());
		Assert.assertEquals(2L, gains.getCollections());
		Assert.assertEquals(15L, gains.getBossKc());
		Assert.assertEquals(10L, gains.getBossKc("Vorkath"));
		Assert.assertEquals(5L, gains.getBossKc("Chambers of Xeric"));
	}

	@Test
	public void parsesAllTimeTotalsFromBulkHiscores()
	{
		String json = "[{"
			+ "\"player\":{\"username\":\"alice\",\"displayName\":\"Alice\",\"exp\":999},"
			+ "\"data\":{\"data\":{"
			+ "\"skills\":{\"overall\":{\"experience\":123456789}},"
			+ "\"activities\":{\"collections_logged\":{\"score\":987}},"
			+ "\"bosses\":{\"vorkath\":{\"kills\":1200},\"zulrah\":{\"kills\":-1},"
			+ "\"chambers_of_xeric\":{\"kills\":300}}}}}]";

		JsonArray root = new Gson().fromJson(json, JsonArray.class);
		ClanProgressGains totals = WiseOldManGainsClient.parseGroupAllTime(root).get("Alice");

		Assert.assertNotNull(totals);
		Assert.assertEquals(123456789L, totals.getXp());
		Assert.assertEquals(987L, totals.getCollections());
		Assert.assertEquals(1500L, totals.getBossKc());
		Assert.assertEquals(1200L, totals.getBossKc("Vorkath"));
		Assert.assertEquals(300L, totals.getBossKc("Chambers of Xeric"));
	}

	private static Response response(Request request, int code, String body, String... header)
	{
		Response.Builder response = new Response.Builder()
			.request(request)
			.protocol(Protocol.HTTP_1_1)
			.code(code)
			.message(code == 200 ? "OK" : "Too Many Requests")
			.body(ResponseBody.create(JSON, body));
		if (header.length == 2)
		{
			response.header(header[0], header[1]);
		}
		return response.build();
	}

}

package com.runeversus;

import org.junit.Assert;
import org.junit.Test;

public class RequestGenerationTest
{
	@Test
	public void onlyLatestRequestRemainsCurrent()
	{
		RequestGeneration requests = new RequestGeneration();
		long first = requests.next();
		long second = requests.next();

		Assert.assertFalse(requests.isCurrent(first));
		Assert.assertTrue(requests.isCurrent(second));

		requests.invalidate();
		Assert.assertFalse(requests.isCurrent(second));
	}
}

package com.runeversus;

import java.io.File;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.Map;
import javax.imageio.ImageIO;

public class ClanProgressCardPreview
{
	public static void main(String[] args) throws Exception
	{
		ClanProgressLeaderboard leaderboard = new ClanProgressLeaderboard(
			"Example Clan",
			139,
			Arrays.asList(
				player("Lynx Titan", 9_800_000, 38_400_000, 141_000_000, 812_000_000, 1, 7, 24, 101, 32, 184, 640, 4_280),
				player("Collectionist", 4_200_000, 21_700_000, 95_000_000, 504_000_000, 6, 19, 58, 244, 18, 226, 980, 5_760),
				player("Raid Captain", 6_100_000, 29_600_000, 172_000_000, 733_000_000, 3, 11, 41, 190, 94, 418, 1_740, 8_930)));

		File out = new File(args.length == 0
			? "build/previews/runeversus-clan-progress-preview.png"
			: args[0]);
		File parent = out.getParentFile();
		if (parent != null && !parent.exists())
		{
			parent.mkdirs();
		}
		ImageIO.write(new RuneVersusCardRenderer().renderClanProgress(
			leaderboard, RuneVersusCardTheme.CLAN_WAR), "png", out);
		System.out.println(out.getAbsolutePath());
	}

	private static ClanProgressPlayer player(
		String name,
		long dayXp, long weekXp, long monthXp, long yearXp,
		long dayClogs, long weekClogs, long monthClogs, long yearClogs,
		long dayKc, long weekKc, long monthKc, long yearKc)
	{
		Map<GainPeriod, ClanProgressGains> gains = new EnumMap<>(GainPeriod.class);
		gains.put(GainPeriod.DAY, new ClanProgressGains(dayXp, dayClogs, dayKc));
		gains.put(GainPeriod.WEEK, new ClanProgressGains(weekXp, weekClogs, weekKc));
		gains.put(GainPeriod.MONTH, new ClanProgressGains(monthXp, monthClogs, monthKc));
		gains.put(GainPeriod.YEAR, new ClanProgressGains(yearXp, yearClogs, yearKc));
		gains.put(GainPeriod.ALL_TIME, new ClanProgressGains(yearXp * 6, yearClogs * 6, yearKc * 6));
		return new ClanProgressPlayer(name, gains);
	}
}

package com.runeversus;

import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class MonthlyLeagueRosterTest
{
	private static final Instant START = Instant.parse("2026-07-01T00:00:00Z");

	@Test
	public void firstCaptureMarksOnlyVerifiedEarlyMembersAsEligible()
	{
		List<MonthlyLeagueParticipant> gains = Arrays.asList(
			gain(1L, "Early", START.plusSeconds(3_600L)),
			gain(2L, "Unknown", START.plusSeconds(3_600L)));
		List<MonthlyLeagueMembership> memberships = Collections.singletonList(
			new MonthlyLeagueMembership(1L, "Early", "regular", START.minusSeconds(86_400L)));

		List<MonthlyLeagueParticipant> merged = RuneVersusService.mergeMonthlyParticipants(
			START, null, gains, memberships);

		Assert.assertTrue(find(merged, "Early").isRosterEligible());
		Assert.assertFalse(find(merged, "Unknown").isRosterEligible());
	}

	@Test
	public void capturesEligibleMembersWhoJoinDuringGraceBeforeRosterFreeze()
	{
		MonthlyLeagueParticipant early = new MonthlyLeagueParticipant(
			1L, "Early", "regular", 1, 1, 0,
			START, START.plusSeconds(3_600L), START.minusSeconds(3_600L), true);
		MonthlyLeagueArchiveStore.Archive previous = new MonthlyLeagueArchiveStore.Archive(
			null, null, Collections.singletonList(early));
		List<MonthlyLeagueParticipant> gains = Arrays.asList(
			gain(1L, "Early", START),
			gain(2L, "Grace", START.plusSeconds(2 * 86_400L)));
		List<MonthlyLeagueMembership> memberships = Arrays.asList(
			new MonthlyLeagueMembership(1L, "Early", "regular", START.minusSeconds(3_600L)),
			new MonthlyLeagueMembership(2L, "Grace", "regular", START.plusSeconds(2 * 86_400L)));

		List<MonthlyLeagueParticipant> merged = RuneVersusService.mergeMonthlyParticipants(
			START, previous, gains, memberships);

		Assert.assertTrue(find(merged, "Early").isRosterEligible());
		Assert.assertTrue(find(merged, "Grace").isRosterEligible());
	}

	@Test
	public void laterCapturesCannotAddCompetitiveMembersOrDropFrozenOnes()
	{
		MonthlyLeagueParticipant frozen = new MonthlyLeagueParticipant(
			1L, "Frozen", "regular", 5, 4, 1,
			START, START.plusSeconds(86_400L), START.minusSeconds(86_400L), true);
		MonthlyLeagueArchiveStore.Archive previous = new MonthlyLeagueArchiveStore.Archive(
			START.plusSeconds(3_600L), null, Collections.singletonList(frozen));
		List<MonthlyLeagueParticipant> currentGains = Collections.singletonList(
			gain(2L, "Newcomer", START.plusSeconds(2 * 86_400L)));
		List<MonthlyLeagueMembership> memberships = Collections.singletonList(
			new MonthlyLeagueMembership(2L, "Newcomer", "regular", START.plusSeconds(2 * 86_400L)));

		List<MonthlyLeagueParticipant> merged = RuneVersusService.mergeMonthlyParticipants(
			START, previous, currentGains, memberships);

		Assert.assertTrue(find(merged, "Frozen").isRosterEligible());
		Assert.assertFalse(find(merged, "Newcomer").isRosterEligible());
	}

	@Test
	public void preservesEarlyMemberCandidateUntilTheirFirstSnapshotAppears()
	{
		MonthlyLeagueMembership membership = new MonthlyLeagueMembership(
			3L, "Pending", "regular", START.minusSeconds(3_600L));
		List<MonthlyLeagueParticipant> first = RuneVersusService.mergeMonthlyParticipants(
			START, null, Collections.emptyList(), Collections.singletonList(membership));
		MonthlyLeagueParticipant pending = find(first, "Pending");
		Assert.assertTrue(pending.isRosterEligible());

		MonthlyLeagueArchiveStore.Archive previous = new MonthlyLeagueArchiveStore.Archive(
			null, null, first);
		List<MonthlyLeagueParticipant> second = RuneVersusService.mergeMonthlyParticipants(
			START, previous,
			Collections.singletonList(gain(3L, "Pending", START.plusSeconds(2 * 3_600L))),
			Collections.singletonList(membership));

		Assert.assertTrue(find(second, "Pending").isRosterEligible());
		MonthlyLeagueSeason season = new MonthlyLeagueSeason(
			42, java.time.YearMonth.of(2026, 7), START.plusSeconds(86_400L), second);
		Assert.assertEquals(1, season.getEligibleCount());
	}

	private static MonthlyLeagueParticipant gain(long id, String name, Instant trackedFrom)
	{
		return new MonthlyLeagueParticipant(
			id, name, "regular", 1, 1, 1, trackedFrom, trackedFrom.plusSeconds(3_600L));
	}

	private static MonthlyLeagueParticipant find(List<MonthlyLeagueParticipant> participants, String name)
	{
		return participants.stream()
			.filter(participant -> name.equals(participant.getName()))
			.findFirst()
			.orElseThrow(AssertionError::new);
	}
}

package com.runeversus;

import java.awt.image.BufferedImage;
import java.io.File;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.swing.SwingUtilities;

public class ClanProgressPanelPreview
{
	public static void main(String[] args) throws Exception
	{
		File out = new File(args.length == 0
			? "build/previews/runeversus-clan-panel-preview.png"
			: args[0]);
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				ClanProgressPanel panel = new ClanProgressPanel(() -> { }, () -> { }, ignored -> { }, () -> true);
				panel.setLeaderboard(sampleLeaderboard());
				panel.selectPeriod(GainPeriod.ALL_TIME);
				panel.selectBoss("Vorkath");
				panel.setSize(1100, 820);
				layout(panel);
				BufferedImage image = new BufferedImage(1100, 820, BufferedImage.TYPE_INT_ARGB);
				panel.printAll(image.createGraphics());
				File parent = out.getParentFile();
				if (parent != null && !parent.exists())
				{
					parent.mkdirs();
				}
				ImageIO.write(image, "png", out);
			}
			catch (Exception ex)
			{
				throw new IllegalStateException(ex);
			}
		});
		System.out.println(out.getAbsolutePath());
	}

	private static ClanProgressLeaderboard sampleLeaderboard()
	{
		List<ClanProgressPlayer> players = new ArrayList<>();
		for (int i = 1; i <= 18; i++)
		{
			Map<GainPeriod, ClanProgressGains> gains = new EnumMap<>(GainPeriod.class);
			for (GainPeriod period : GainPeriod.values())
			{
				long multiplier = period.ordinal() + 1L;
				gains.put(period, new ClanProgressGains(
					(19L - i) * 740_000L * multiplier,
					(i * 3L + period.ordinal()) % 11L,
					java.util.Map.of(
						"Vorkath", (19L - i) * 5L * multiplier,
						"Zulrah", (19L - i) * 3L * multiplier)));
			}
			players.add(new ClanProgressPlayer(i == 1 ? "Raid Captain" : "Clan Member " + i, gains));
		}
		return new ClanProgressLeaderboard("Clan progress", 139, players);
	}

	private static void layout(java.awt.Container root)
	{
		root.doLayout();
		for (java.awt.Component component : root.getComponents())
		{
			if (component instanceof java.awt.Container)
			{
				layout((java.awt.Container) component);
			}
		}
	}
}

