package com.runeversus;

import javax.swing.JButton;
import javax.swing.Timer;

/**
 * Shows a short confirmation on a button and restores its label afterwards.
 * The Swing timer fires on the event dispatch thread, so no extra thread is started.
 */
final class ButtonFlash
{
	private static final String ORIGINAL_TEXT = "runeVersusOriginalText";
	private static final String ACTIVE_TIMER = "runeVersusFlashTimer";
	private static final int RESET_DELAY_MILLIS = 1_500;

	private ButtonFlash()
	{
	}

	static void confirm(JButton button, String message)
	{
		Timer active = (Timer) button.getClientProperty(ACTIVE_TIMER);
		if (active == null)
		{
			// Only the first flash records the label, so repeated clicks cannot
			// capture a confirmation message as the text to restore.
			button.putClientProperty(ORIGINAL_TEXT, button.getText());
		}
		else
		{
			active.stop();
		}

		button.setText(message);
		Timer timer = new Timer(RESET_DELAY_MILLIS, e ->
		{
			button.setText((String) button.getClientProperty(ORIGINAL_TEXT));
			button.putClientProperty(ACTIVE_TIMER, null);
		});
		timer.setRepeats(false);
		button.putClientProperty(ACTIVE_TIMER, timer);
		timer.start();
	}
}

