import net.runelite.client.hiscore.HiscoreClient;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import net.runelite.client.hiscore.Skill;

@Singleton
public class RuneVersusService
{
	private static final Duration MONTHLY_LEAGUE_CACHE_TTL = Duration.ofMinutes(30);
	private static final int MAX_LEAGUE_CACHE_ENTRIES = 64;
	private static final HiscoreSkill[] PUBLIC_COLLECTION_METRICS = {
		HiscoreSkill.COLLECTIONS_LOGGED,
		HiscoreSkill.CLUE_SCROLL_ALL,
		HiscoreSkill.CLUE_SCROLL_MASTER,
		HiscoreSkill.CLUE_SCROLL_ELITE,
		HiscoreSkill.CLUE_SCROLL_HARD
	};

	private final HiscoreClient hiscoreClient;
	private final WiseOldManGainsClient wiseOldManGainsClient;
	private final MonthlyLeagueArchiveStore monthlyLeagueArchiveStore;
	private final RuneVersusConfig config;
	private final ScheduledExecutorService executor;
	private final Map<String, CachedLeague> monthlyLeagueCache = Collections.synchronizedMap(
		new LinkedHashMap<String, CachedLeague>(16, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, CachedLeague> eldest)
			{
				return size() > MAX_LEAGUE_CACHE_ENTRIES;
			}
		});

	@Inject
	public RuneVersusService(
		HiscoreClient hiscoreClient,
		WiseOldManGainsClient wiseOldManGainsClient,
		MonthlyLeagueArchiveStore monthlyLeagueArchiveStore,
		RuneVersusConfig config,
		ScheduledExecutorService executor)
	{
		this.hiscoreClient = hiscoreClient;
		this.wiseOldManGainsClient = wiseOldManGainsClient;
		this.monthlyLeagueArchiveStore = monthlyLeagueArchiveStore;
		this.config = config;
		this.executor = executor;
	}

	public CompletableFuture<DuelResult> compare(String leftName, String rightName)
	{
		final String left;
		final String right;
		try
		{
			left = OsrsPlayerName.requireValid(leftName);
			right = OsrsPlayerName.requireValid(rightName);
		}
		catch (IllegalArgumentException ex)
		{
			CompletableFuture<DuelResult> failed = new CompletableFuture<>();
			failed.completeExceptionally(ex);
			return failed;
		}
		// Both sides are independent lookups, so fetch them concurrently instead of
		// making the second player wait for the first.
		CompletableFuture<PlayerProfile> leftProfile =
			CompletableFuture.supplyAsync(() -> loadProfileUnchecked(left), executor);
		CompletableFuture<PlayerProfile> rightProfile =
			CompletableFuture.supplyAsync(() -> loadProfileUnchecked(right), executor);
		return leftProfile.thenCombine(rightProfile, this::buildDuel);
	}

	public CompletableFuture<ClanProgressLeaderboard> analyzeClanProgress(String label, int groupId)
	{
		return analyzeClanProgress(label, groupId, false);
	}

	public CompletableFuture<ClanProgressLeaderboard> analyzeClanProgress(
		String label,
		int groupId,
		boolean forceRefresh)
	{
		return CompletableFuture.supplyAsync(() ->
		{
			Map<String, String> displayNames = new LinkedHashMap<>();
			Map<String, EnumMap<GainPeriod, ClanProgressGains>> gainsByPlayer = new LinkedHashMap<>();
			try
			{
				for (GainPeriod period : GainPeriod.values())
				{
					Map<String, ClanProgressGains> periodGains = wiseOldManGainsClient.getGroupGains(
						groupId, period, forceRefresh);
					for (Map.Entry<String, ClanProgressGains> entry : periodGains.entrySet())
					{
						String key = normalizedName(entry.getKey());
						displayNames.putIfAbsent(key, entry.getKey());
						gainsByPlayer.computeIfAbsent(key, ignored -> new EnumMap<>(GainPeriod.class))
							.put(period, entry.getValue());
					}
				}
			}
			catch (IOException ex)
			{
				throw new IllegalStateException(ex);
			}

			List<ClanProgressPlayer> players = new ArrayList<>();
			for (Map.Entry<String, EnumMap<GainPeriod, ClanProgressGains>> entry : gainsByPlayer.entrySet())
			{
				players.add(new ClanProgressPlayer(displayNames.get(entry.getKey()), entry.getValue()));
			}
			players.sort(java.util.Comparator.comparing(ClanProgressPlayer::getName, String.CASE_INSENSITIVE_ORDER));
			return new ClanProgressLeaderboard(label, groupId, players);
		}, executor);
	}

	public CompletableFuture<MonthlyLeagueSeason> analyzeMonthlyLeague(
		int groupId,
		YearMonth month,
		boolean forceRefresh)
	{
		if (groupId <= 0 || month == null)
		{
			CompletableFuture<MonthlyLeagueSeason> failed = new CompletableFuture<>();
			failed.completeExceptionally(new IllegalArgumentException("A WOM group and season are required"));
			return failed;
		}

		Instant now = Instant.now();
		String cacheKey = groupId + ":" + month;
		MonthlyLeagueArchiveStore.Archive archived = monthlyLeagueArchiveStore.load(groupId, month);
		if (archived != null && archived.isFinalized())
		{
			MonthlyLeagueSeason finalSeason = new MonthlyLeagueSeason(
				groupId, month, archived.getFinalizedAt(), archived.getParticipants(), true);
			monthlyLeagueCache.put(cacheKey, new CachedLeague(finalSeason, now));
			return CompletableFuture.completedFuture(finalSeason);
		}
		CachedLeague cached = monthlyLeagueCache.get(cacheKey);
		if (!forceRefresh && cached != null
			&& Duration.between(cached.cachedAt, now).compareTo(MONTHLY_LEAGUE_CACHE_TTL) < 0)
		{
			return CompletableFuture.completedFuture(cached.season);
		}

		return CompletableFuture.supplyAsync(() ->
		{
			Instant fetchedAt = Instant.now();
			Instant startsAt = month.atDay(1).atStartOfDay(ZoneOffset.UTC).toInstant();
			Instant rosterGraceEnd = startsAt.plus(Duration.ofHours(72));
			Instant seasonEnd = month.plusMonths(1).atDay(1).atStartOfDay(ZoneOffset.UTC).toInstant();
			Instant queryEnd = fetchedAt.isBefore(seasonEnd) ? fetchedAt : seasonEnd;
			if (!queryEnd.isAfter(startsAt))
			{
				throw new IllegalStateException("This monthly season has not started yet");
			}
			try
			{
				MonthlyLeagueArchiveStore.Archive previous = monthlyLeagueArchiveStore.load(groupId, month);
				// A sealed season is normally immutable, but an explicit refresh must be
				// able to rebuild one that was archived from incomplete data.
				if (!forceRefresh && previous != null && previous.isFinalized())
				{
					return new MonthlyLeagueSeason(
						groupId, month, previous.getFinalizedAt(), previous.getParticipants(), true);
				}
				List<MonthlyLeagueParticipant> gains = wiseOldManGainsClient.getMonthlyLeagueGains(
					groupId, startsAt, queryEnd, forceRefresh);
				List<MonthlyLeagueMembership> memberships = wiseOldManGainsClient.getGroupMemberships(
					groupId, forceRefresh);
				List<MonthlyLeagueParticipant> participants = mergeMonthlyParticipants(
					startsAt, previous, gains, memberships);
				boolean finalized = !fetchedAt.isBefore(seasonEnd);
				Instant frozenAt = previous != null && previous.getFrozenAt() != null
					? previous.getFrozenAt()
					: !fetchedAt.isBefore(rosterGraceEnd) ? fetchedAt : null;
				Instant finalizedAt = finalized ? fetchedAt : null;
				monthlyLeagueArchiveStore.save(
					groupId, month, frozenAt, finalizedAt, participants);
				MonthlyLeagueSeason season = new MonthlyLeagueSeason(
					groupId,
					month,
					fetchedAt,
					participants,
					finalized);
				monthlyLeagueCache.put(cacheKey, new CachedLeague(season, fetchedAt));
				return season;
			}
			catch (IOException ex)
			{
				throw new IllegalStateException(ex);
			}
		}, executor);
	}

	static List<MonthlyLeagueParticipant> mergeMonthlyParticipants(
		Instant startsAt,
		MonthlyLeagueArchiveStore.Archive previous,
		List<MonthlyLeagueParticipant> gains,
		List<MonthlyLeagueMembership> memberships)
	{
		Instant graceEnd = startsAt.plus(Duration.ofHours(72));
		boolean rosterFrozen = previous != null && previous.getFrozenAt() != null;
		Map<String, MonthlyLeagueParticipant> previousByKey = new LinkedHashMap<>();
		if (previous != null)
		{
			for (MonthlyLeagueParticipant participant : previous.getParticipants())
			{
				previousByKey.put(participantKey(participant.getPlayerId(), participant.getName()), participant);
			}
		}

		Map<String, MonthlyLeagueMembership> membershipsByKey = new LinkedHashMap<>();
		if (memberships != null)
		{
			for (MonthlyLeagueMembership membership : memberships)
			{
				membershipsByKey.put(participantKey(membership.getPlayerId(), membership.getName()), membership);
			}
		}

		Map<String, MonthlyLeagueParticipant> merged = new LinkedHashMap<>();
		if (gains != null)
		{
			for (MonthlyLeagueParticipant gain : gains)
			{
				String key = participantKey(gain.getPlayerId(), gain.getName());
				MonthlyLeagueParticipant old = previousByKey.remove(key);
				MonthlyLeagueMembership membership = membershipsByKey.remove(key);
				Instant joinedAt = old != null && old.getJoinedAt() != null
					? old.getJoinedAt() : membership == null ? null : membership.getJoinedAt();
				boolean eligibleAtFreeze;
				if (old != null && rosterFrozen)
				{
					eligibleAtFreeze = old.isRosterEligible();
				}
				else if (rosterFrozen)
				{
					eligibleAtFreeze = false;
				}
				else
				{
					// joinedAt is only used to confirm the player is a known group member;
					// its value is the WOM record creation date, not a clan join date.
					eligibleAtFreeze = joinedAt != null
						&& gain.getTrackedFrom() != null
						&& !gain.getTrackedFrom().isAfter(graceEnd);
				}
				merged.put(key, new MonthlyLeagueParticipant(
					gain.getPlayerId(),
					gain.getName(),
					gain.getAccountType(),
					gain.getEhpGained(),
					gain.getEhbGained(),
					gain.getCollectionsGained(),
					gain.getTrackedFrom(),
					gain.getTrackedUntil(),
					joinedAt,
					eligibleAtFreeze));
			}
		}

		for (Map.Entry<String, MonthlyLeagueParticipant> missing : previousByKey.entrySet())
		{
			MonthlyLeagueMembership membership = membershipsByKey.remove(missing.getKey());
			if (rosterFrozen || membership != null)
			{
				MonthlyLeagueParticipant old = missing.getValue();
				boolean eligible = rosterFrozen
					? old.isRosterEligible()
					: old.getJoinedAt() != null
						&& old.getTrackedFrom() != null
						&& !old.getTrackedFrom().isAfter(graceEnd);
				merged.putIfAbsent(missing.getKey(), new MonthlyLeagueParticipant(
					old.getPlayerId(),
					old.getName(),
					old.getAccountType(),
					old.getEhpGained(),
					old.getEhbGained(),
					old.getCollectionsGained(),
					old.getTrackedFrom(),
					old.getTrackedUntil(),
					old.getJoinedAt(),
					eligible));
			}
		}
		for (MonthlyLeagueMembership membership : membershipsByKey.values())
		{
			String key = participantKey(membership.getPlayerId(), membership.getName());
			boolean frozenCandidate = !rosterFrozen
				&& membership.getJoinedAt() != null
				&& !membership.getJoinedAt().isAfter(graceEnd);
			merged.putIfAbsent(key, new MonthlyLeagueParticipant(
				membership.getPlayerId(),
				membership.getName(),
				membership.getAccountType(),
				0.0,
				0.0,
				0L,
				null,
				null,
				membership.getJoinedAt(),
				frozenCandidate));
		}
		return new ArrayList<>(merged.values());
	}

	private static String participantKey(long playerId, String name)
	{
		return playerId > 0L ? "id:" + playerId : "name:" + normalizedName(name);
	}

	private PlayerProfile loadProfileUnchecked(String name)
	{
		try
		{
			return loadProfile(name);
		}
		catch (IOException ex)
		{
			throw new IllegalStateException(ex);
		}
	}

	private PlayerProfile loadProfile(String name) throws IOException
	{
		HiscoreResult result = hiscoreClient.lookup(name, config.hiscoreEndpoint());
		if (result == null)
		{
			throw new IOException("No hiscore data for " + name);
		}

		if (!config.wiseOldManGains())
		{
			return new PlayerProfile(name, result);
		}

		Map<HiscoreSkill, Long> day = safeGains(name, "day");
		Map<HiscoreSkill, Long> week = safeGains(name, "week");
		Map<HiscoreSkill, Long> month = safeGains(name, "month");
		return new PlayerProfile(name, result, day, week, month, !day.isEmpty() || !week.isEmpty() || !month.isEmpty());
	}

	private Map<HiscoreSkill, Long> safeGains(String name, String period)
	{
		try
		{
			return wiseOldManGainsClient.getSkillExperienceGains(name, period);
		}
		catch (IOException ex)
		{
			return Collections.emptyMap();
		}
	}

	private DuelResult buildDuel(PlayerProfile left, PlayerProfile right)
	{
		List<MetricResult> skills = new ArrayList<>();
		List<MetricResult> bosses = new ArrayList<>();
		List<MetricResult> activities = new ArrayList<>();

		for (HiscoreSkill hiscoreSkill : HiscoreSkill.values())
		{
			if (hiscoreSkill.getType() == HiscoreSkillType.SKILL || hiscoreSkill == HiscoreSkill.OVERALL)
			{
				long leftValue = skillExperience(left.getHiscores(), hiscoreSkill);
				long rightValue = skillExperience(right.getHiscores(), hiscoreSkill);
				if (leftValue > 0 || rightValue > 0)
				{
					skills.add(new MetricResult(MetricType.SKILL, hiscoreSkill.getName(), leftValue, rightValue));
				}
			}
			else if (hiscoreSkill.getType() == HiscoreSkillType.BOSS)
			{
				long leftValue = score(left.getHiscores(), hiscoreSkill);
				long rightValue = score(right.getHiscores(), hiscoreSkill);
				if (leftValue > 0 || rightValue > 0)
				{
					bosses.add(new MetricResult(MetricType.BOSS, hiscoreSkill.getName(), leftValue, rightValue));
				}
			}
		}

		for (HiscoreSkill metric : PUBLIC_COLLECTION_METRICS)
		{
			long leftValue = score(left.getHiscores(), metric);
			long rightValue = score(right.getHiscores(), metric);
			if (leftValue > 0 || rightValue > 0)
			{
				MetricType type = metric == HiscoreSkill.COLLECTIONS_LOGGED
					? MetricType.COLLECTION_LOG
					: MetricType.ACTIVITY;
				activities.add(new MetricResult(type, metric.getName(), leftValue, rightValue));
			}
		}

		return new DuelResult(
			left,
			right,
			skills,
			bosses,
			activities,
			formMetrics(MetricType.FORM_DAY, left.getDayGains(), right.getDayGains()),
			formMetrics(MetricType.FORM_WEEK, left.getWeekGains(), right.getWeekGains()),
			formMetrics(MetricType.FORM_MONTH, left.getMonthGains(), right.getMonthGains()));
	}

	private static List<MetricResult> formMetrics(MetricType type, Map<HiscoreSkill, Long> left, Map<HiscoreSkill, Long> right)
	{
		if ((left == null || left.isEmpty()) && (right == null || right.isEmpty()))
		{
			return Collections.emptyList();
		}

		Map<HiscoreSkill, Long> leftValues = left == null ? Collections.emptyMap() : left;
		Map<HiscoreSkill, Long> rightValues = right == null ? Collections.emptyMap() : right;
		List<MetricResult> out = new ArrayList<>();
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill == HiscoreSkill.OVERALL || skill.getType() == HiscoreSkillType.SKILL)
			{
				long leftValue = leftValues.getOrDefault(skill, 0L);
				long rightValue = rightValues.getOrDefault(skill, 0L);
				if (leftValue != 0 || rightValue != 0)
				{
					out.add(new MetricResult(type, skill.getName(), leftValue, rightValue));
				}
			}
		}
		return out;
	}

	private static long skillExperience(HiscoreResult result, HiscoreSkill skill)
	{
		Skill s = result.getSkill(skill);
		if (s == null)
		{
			return 0L;
		}
		if (s.getExperience() >= 0)
		{
			return s.getExperience();
		}
		return Math.max(0, s.getLevel());
	}

	private static long score(HiscoreResult result, HiscoreSkill skill)
	{
		Skill s = result.getSkill(skill);
		if (s == null)
		{
			return 0L;
		}
		return Math.max(0, s.getLevel());
	}

	private static String cleanName(String name)
	{
		return name == null ? "" : name.trim();
	}

	private static String normalizedName(String name)
	{
		return cleanName(name).replace('\u00a0', ' ').toLowerCase(Locale.ROOT);
	}

	private static final class CachedLeague
	{
		private final MonthlyLeagueSeason season;
		private final Instant cachedAt;

		private CachedLeague(MonthlyLeagueSeason season, Instant cachedAt)
		{
			this.season = season;
			this.cachedAt = cachedAt;
		}
	}
}

package com.runeversus;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

public class ClanProgressLeaderboard
{
	private final String label;
	private final int groupId;
	private final List<ClanProgressPlayer> players;
	private final Instant createdAt;

	public ClanProgressLeaderboard(String label, int groupId, List<ClanProgressPlayer> players)
	{
		this.label = label;
		this.groupId = groupId;
		this.players = Collections.unmodifiableList(new ArrayList<>(players));
		this.createdAt = Instant.now();
	}

	public String getLabel()
	{
		return label;
	}

	public int getGroupId()
	{
		return groupId;
	}

	public List<ClanProgressPlayer> getPlayers()
	{
		return players;
	}

	public Instant getCreatedAt()
	{
		return createdAt;
	}

	public ClanProgressPlayer getLeader(GainPeriod period, ClanProgressMetric metric)
	{
		Comparator<ClanProgressPlayer> comparator = Comparator
			.comparingLong((ClanProgressPlayer player) -> player.getGains(period).valueFor(metric))
			.reversed()
			.thenComparing(ClanProgressPlayer::getName, String.CASE_INSENSITIVE_ORDER);
		return players.stream()
			.filter(player -> player.getGains(period).valueFor(metric) > 0L)
			.min(comparator)
			.orElse(null);
	}

	public long getLeaderValue(GainPeriod period, ClanProgressMetric metric)
	{
		ClanProgressPlayer leader = getLeader(period, metric);
		return leader == null ? 0L : leader.getGains(period).valueFor(metric);
	}

	public ClanProgressPlayer getBossLeader(GainPeriod period, String bossName)
	{
		Comparator<ClanProgressPlayer> comparator = Comparator
			.comparingLong((ClanProgressPlayer player) -> player.getGains(period).getBossKc(bossName))
			.reversed()
			.thenComparing(ClanProgressPlayer::getName, String.CASE_INSENSITIVE_ORDER);
		return players.stream()
			.filter(player -> player.getGains(period).getBossKc(bossName) > 0L)
			.min(comparator)
			.orElse(null);
	}

	public List<String> getBossNames()
	{
		Set<String> names = new LinkedHashSet<>(BossKcRegistry.allNames());
		for (ClanProgressPlayer player : players)
		{
			for (GainPeriod period : GainPeriod.values())
			{
				names.addAll(player.getGains(period).getBossKcByBoss().keySet());
			}
		}
		List<String> sorted = new ArrayList<>(names);
		sorted.sort(String.CASE_INSENSITIVE_ORDER);
		return Collections.unmodifiableList(sorted);
	}

	public List<String> toChatLines()
	{
		List<String> lines = new ArrayList<>();
		for (GainPeriod period : GainPeriod.values())
		{
			lines.add("[RV] " + period.getLabel()
				+ " | XP: " + leaderText(period, ClanProgressMetric.XP)
				+ " | CLogs: " + leaderText(period, ClanProgressMetric.COLLECTIONS)
				+ " | Boss KC: " + leaderText(period, ClanProgressMetric.BOSS_KC));
		}
		return lines;
	}

	public String toDisplayText()
	{
		if (players.isEmpty())
		{
			return "[RuneVersus] No tracked players found for Wise Old Man group #" + groupId + ".";
		}
		StringBuilder out = new StringBuilder("[RuneVersus] ")
			.append(label)
			.append(" • ")
			.append(players.size())
			.append(" WOM player(s)\n");
		for (String line : toChatLines())
		{
			out.append(line.substring(5)).append('\n');
		}
		return out.toString().trim();
	}

	private String leaderText(GainPeriod period, ClanProgressMetric metric)
	{
		ClanProgressPlayer leader = getLeader(period, metric);
		if (leader == null)
		{
			return "no gain";
		}
		long value = leader.getGains(period).valueFor(metric);
		return leader.getName() + " " + valueText(period, value);
	}

	static String valueText(GainPeriod period, long value)
	{
		return (period.isAllTime() ? "" : "+") + RuneVersusFlavor.format(value);
	}
}

package com.runeversus;

import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;

final class LimitedInputStream extends FilterInputStream
{
	private final long limit;
	private long consumed;

	LimitedInputStream(InputStream input, long limit)
	{
		super(input);
		this.limit = limit;
	}

	@Override
	public int read() throws IOException
	{
		int value = super.read();
		if (value >= 0)
		{
			record(1L);
		}
		return value;
	}

	@Override
	public int read(byte[] buffer, int offset, int length) throws IOException
	{
		int allowed = (int) Math.min(length, Math.max(1L, limit - consumed + 1L));
		int count = super.read(buffer, offset, allowed);
		if (count > 0)
		{
			record(count);
		}
		return count;
	}

	private void record(long count) throws IOException
	{
		consumed += count;
		if (consumed > limit)
		{
			throw new IOException("Input exceeds the configured size limit");
		}
	}
}

package com.runeversus;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.hiscore.HiscoreEndpoint;

@ConfigGroup("runeversus")
public interface RuneVersusConfig extends Config
{
	@ConfigSection(
		name = "Player data",
		description = "Choose the account type and optional data sources.",
		position = 0
	)
	String comparisonSection = "comparison";

	@ConfigItem(
		keyName = "hiscoreEndpoint",
		name = "Account type",
		description = "Official hiscore table used for lookups, such as Normal or Ironman.",
		section = comparisonSection,
		position = 0
	)
	default HiscoreEndpoint hiscoreEndpoint()
	{
		return HiscoreEndpoint.NORMAL;
	}

	@ConfigItem(
		keyName = "wiseOldManGains",
		name = "Recent XP details",
		description = "Adds 24h, week, and month XP to cards. Compared names are sent to Wise Old Man.",
		section = comparisonSection,
		position = 1
	)
	default boolean wiseOldManGains()
	{
		return false;
	}

