package com.runeversus;

import java.util.Collections;
import java.util.Map;
import java.util.TreeMap;

public class ClanProgressGains
{
	private final long xp;
	private final long collections;
	private final long bossKc;
	private final Map<String, Long> bossKcByBoss;

	public ClanProgressGains(long xp, long collections, long bossKc)
	{
		this(xp, collections, bossKc, Collections.emptyMap());
	}

	public ClanProgressGains(long xp, long collections, Map<String, Long> bossKcByBoss)
	{
		this(xp, collections, totalBossKc(bossKcByBoss), bossKcByBoss);
	}

	private ClanProgressGains(
		long xp,
		long collections,
		long bossKc,
		Map<String, Long> bossKcByBoss)
	{
		this.xp = Math.max(0L, xp);
		this.collections = Math.max(0L, collections);
		this.bossKc = Math.max(0L, bossKc);
		TreeMap<String, Long> copy = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		if (bossKcByBoss != null)
		{
			for (Map.Entry<String, Long> entry : bossKcByBoss.entrySet())
			{
				if (entry.getKey() != null && entry.getValue() != null && entry.getValue() > 0L)
				{
					copy.put(entry.getKey(), entry.getValue());
				}
			}
		}
		this.bossKcByBoss = Collections.unmodifiableMap(copy);
	}

	public long getXp()
	{
		return xp;
	}

	public long getCollections()
	{
		return collections;
	}

	public long getBossKc()
	{
		return bossKc;
	}

	public long getBossKc(String bossName)
	{
		if (bossName == null || bossName.trim().isEmpty())
		{
			return bossKc;
		}
		return bossKcByBoss.getOrDefault(bossName, 0L);
	}

	public Map<String, Long> getBossKcByBoss()
	{
		return bossKcByBoss;
	}

	public long valueFor(ClanProgressMetric metric)
	{
		switch (metric)
		{
			case XP:
				return xp;
			case COLLECTIONS:
				return collections;
			case BOSS_KC:
				return bossKc;
			default:
				return 0L;
		}
	}

	private static long totalBossKc(Map<String, Long> bossKcByBoss)
	{
		long total = 0L;
		if (bossKcByBoss != null)
		{
			for (Long value : bossKcByBoss.values())
			{
				if (value != null && value > 0L)
				{
					total = saturatedAdd(total, value);
				}
			}
		}
		return total;
	}

	static long saturatedAdd(long left, long right)
	{
		return right > 0L && left > Long.MAX_VALUE - right ? Long.MAX_VALUE : left + right;
	}
}

package com.runeversus;

import java.io.IOException;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.function.LongSupplier;

final class WiseOldManRequestGate
{
	private static final int DEFAULT_MAX_REQUESTS = 18;
	private static final long DEFAULT_WINDOW_MILLIS = 60_000L;
	private static final long DEFAULT_BACKOFF_MILLIS = 60_000L;
	private static final long MAX_BACKOFF_SECONDS = 3_600L;

	private final int maxRequests;
	private final long windowMillis;
	private final LongSupplier clock;
	private final Deque<Long> recentRequests = new ArrayDeque<>();
	private long blockedUntil;

	WiseOldManRequestGate()
	{
		this(DEFAULT_MAX_REQUESTS, DEFAULT_WINDOW_MILLIS, System::currentTimeMillis);
	}

	WiseOldManRequestGate(
		int maxRequests,
		long windowMillis,
		LongSupplier clock)
	{
		this.maxRequests = maxRequests;
		this.windowMillis = windowMillis;
		this.clock = clock;
	}

	synchronized void acquire() throws IOException
	{
		long now = clock.getAsLong();
		if (now < blockedUntil)
		{
			throw new WiseOldManRateLimitException(secondsUntil(blockedUntil, now));
		}

		prune(now);
		if (recentRequests.size() >= maxRequests)
		{
			long retryAt = recentRequests.peekFirst() + windowMillis;
			throw new WiseOldManRateLimitException(secondsUntil(retryAt, now));
		}

		recentRequests.addLast(now);
	}

	synchronized WiseOldManRateLimitException backOff(String retryAfterHeader)
	{
		long now = clock.getAsLong();
		long retrySeconds = parseRetryAfter(retryAfterHeader, now);
		blockedUntil = Math.max(blockedUntil, now + retrySeconds * 1_000L);
		return new WiseOldManRateLimitException(retrySeconds);
	}

	private void prune(long now)
	{
		while (!recentRequests.isEmpty() && now - recentRequests.peekFirst() >= windowMillis)
		{
			recentRequests.removeFirst();
		}
	}

	private static long parseRetryAfter(String header, long now)
	{
		if (header != null)
		{
			String value = header.trim();
			try
			{
				return clampRetrySeconds(Long.parseLong(value));
			}
			catch (NumberFormatException ignored)
			{
				try
				{
					long retryAt = ZonedDateTime.parse(value, DateTimeFormatter.RFC_1123_DATE_TIME)
						.toInstant().toEpochMilli();
					return clampRetrySeconds(secondsUntil(retryAt, now));
				}
				catch (DateTimeParseException ignoredDate)
				{
					// Fall through to a conservative default for malformed server values.
				}
			}
		}
		return DEFAULT_BACKOFF_MILLIS / 1_000L;
	}

	private static long clampRetrySeconds(long seconds)
	{
		return Math.min(MAX_BACKOFF_SECONDS, Math.max(1L, seconds));
	}

	private static long secondsUntil(long target, long now)
	{
		return Math.max(1L, (target - now + 999L) / 1_000L);
	}
}

